// Parse EF API response; pass through as single item with ef_listings array
const data = $input.first()?.json ?? {};
const results = data.results || data.data || [];

const ef_listings = results.map(item => ({
  source: 'empire_flippers',
  source_id: String(item.listing_number || item.id || ''),
  title: item.site_title || item.title || '',
  url: `https://empireflippers.com/listing/${item.listing_number || item.id}`,
  asking_price: item.listing_price || item.price || null,
  mrr: item.monthly_net_profit || item.mrr || null,
  annual_profit: item.annual_net_profit || item.annual_profit || null,
  niche: item.niche || item.category || '',
  monetization: Array.isArray(item.monetization) ? item.monetization.join(', ') : (item.monetization || ''),
  description: item.listing_summary || item.summary || '',
})).filter(l => l.source_id);

// Pass single item downstream so Fetch Microns runs exactly once
return [{ json: { ef_listings } }];

// Get EF data accumulated from ancestor node
const ef_listings = $('Parse Empire Flippers').first()?.json?.ef_listings ?? [];

// Parse Microns RSS (XML as text)
const xml = $input.first()?.json?.data ?? '';
const microns_listings = [];

if (xml) {
  const itemRe = /<item>([\s\S]*?)<\/item>/g;
  let m;
  while ((m = itemRe.exec(xml)) !== null) {
    const block = m[1];
    const get = (tag) => {
      const r = new RegExp(`<${tag}>(?:<!\\[CDATA\\[([\\s\\S]*?)\\]\\]>|([^<]*))`, 'i');
      const match = r.exec(block);
      return (match?.[1] || match?.[2] || '').trim();
    };
    const title = get('title');
    const link = get('link') || get('guid');
    const desc = get('description').replace(/<[^>]+>/g, '').trim().slice(0, 400);
    if (title && link) {
      microns_listings.push({
        source: 'microns',
        source_id: link.split('/').filter(Boolean).pop() || title.slice(0, 40),
        title,
        url: link,
        asking_price: null, mrr: null, annual_profit: null,
        niche: '', monetization: '', description: desc,
      });
    }
  }
}

return [{ json: { ef_listings, microns_listings } }];

// Retrieve accumulated data from ancestor nodes
const ef_listings = $('Parse Empire Flippers').first()?.json?.ef_listings ?? [];
const microns_listings = $('Parse Microns + Combine EF').first()?.json?.microns_listings ?? [];

// Parse Flippa response
const flippaRaw = $input.first()?.json ?? {};
const flippaItems = flippaRaw.data || flippaRaw.listings || flippaRaw.results || [];
const flippa_listings = flippaItems.map(item => {
  const a = item.attributes || item;
  return {
    source: 'flippa',
    source_id: String(item.id || a.id || ''),
    title: a.title || a.site_name || '',
    url: a.url?.startsWith('http') ? a.url : `https://flippa.com/listing/${item.id}`,
    asking_price: a.buy_it_now_price || a.current_price || a.price || null,
    mrr: a.average_monthly_revenue || a.revenue || null,
    annual_profit: a.average_monthly_profit ? Number(a.average_monthly_profit) * 12 : null,
    niche: a.property_type || a.site_type || '',
    monetization: a.revenue_sources || '',
    description: a.summary || a.description || '',
  };
}).filter(l => l.source_id);

// Pet & Wellness keywords
const KEYWORDS = [
  'pet','pets','dog','dogs','cat','cats','puppy','puppies',
  'kitten','kittens','veterinary','vet ','vets','animal','animals',
  'grooming','pet care','pet food','pet health','pet shop','pet store',
  'pet supply','pet sitting','dog walking','pet insurance',
  'pet tracker','pet app','pet training','宠物',
  'rabbit','hamster','aquarium','reptile','ferret',
  'wellness','well-being','wellbeing',
  'supplement','nutraceutical',
  'cbd','hemp','thc',
  'meditation','mindfulness',
  'holistic health','natural health',
  'mental wellness','mental health app',
  'sleep tracker','sleep app',
  'probiotic','gut health',
  'fitness tracker','health tracker',
  'telehealth','telemedicine',
  'health coaching','wellness coaching',
  'yoga app','meditation app','健康',
];

const all = [...ef_listings, ...microns_listings, ...flippa_listings];
const relevant = all.filter(l => {
  const text = `${l.title} ${l.description} ${l.niche} ${l.monetization}`.toLowerCase();
  return KEYWORDS.some(kw => text.includes(kw));
});

return [{
  json: {
    scraped_at: new Date().toISOString(),
    total_scraped: all.length,
    sources: {
      empire_flippers: ef_listings.length,
      microns: microns_listings.length,
      flippa: flippa_listings.length,
    },
    pet_wellness_count: relevant.length,
    listings: relevant,
  }
}];

const data = $input.first().json;
const listings = data.listings || [];
const today = new Date().toLocaleDateString('zh-CN', {
  timeZone: 'Asia/Shanghai',
  year: 'numeric', month: 'long', day: 'numeric'
});

const fmtPrice = (p) => p ? `$${Number(p).toLocaleString()}` : '—';
const fmtMrr = (m) => m ? ` | MRR ${fmtPrice(m)}/mo` : '';

const elements = [
  {
    tag: 'div',
    text: {
      tag: 'lark_md',
      content: [
        `**扫描**: ${data.total_scraped} 个项目  |  **匹配**: ${data.pet_wellness_count} 个`,
        `来源: EF ${data.sources.empire_flippers} · Microns ${data.sources.microns} · Flippa ${data.sources.flippa}`,
      ].join('\n')
    }
  },
  { tag: 'hr' },
];

for (const l of listings.slice(0, 10)) {
  elements.push({
    tag: 'div',
    text: {
      tag: 'lark_md',
      content: [
        `**[${l.title}](${l.url})**`,
        `来源: \`${l.source}\` · 要价: ${fmtPrice(l.asking_price)}${fmtMrr(l.mrr)}`,
        l.description ? l.description.slice(0, 100).replace(/\n/g, ' ') + '…' : '',
      ].filter(Boolean).join('\n')
    }
  });
  elements.push({ tag: 'hr' });
}

if (listings.length > 10) {
  elements.push({
    tag: 'div',
    text: { tag: 'lark_md', content: `_另有 ${listings.length - 10} 个项目，[查看完整数据](https://github.com/zacteqye72-art/deal-sourcer/blob/main/data/pet_wellness.json)_` }
  });
}

return [{
  json: {
    msg_type: 'interactive',
    card: {
      config: { wide_screen_mode: true },
      header: {
        template: 'blue',
        title: { tag: 'plain_text', content: `🐾 宠物 & Wellness 日报 · ${today}` }
      },
      elements
    }
  }
}];
